describe("doctests of sympy.series.limitseq", () => {
  it("limit_seq((5*n**3 + 3*n**2 + 4) / (3*n**3 + 4*n - 5), n)", () => {
    const n = new Sym('n');
    expect(sympyStr(limitSeq(mul(pow(add(Rational.of(-5n, 1n, { gcd: 1n }), mul(Rational.of(3n, 1n, { gcd: 1n }), pow(n, Rational.of(3n, 1n, { gcd: 1n }))), mul(Rational.of(4n, 1n, { gcd: 1n }), n)), Rational.of(-1n, 1n, { gcd: 1n })), add(Rational.of(4n, 1n, { gcd: 1n }), mul(Rational.of(3n, 1n, { gcd: 1n }), pow(n, Rational.of(2n, 1n, { gcd: 1n }))), mul(Rational.of(5n, 1n, { gcd: 1n }), pow(n, Rational.of(3n, 1n, { gcd: 1n }))))), n))).toBe('5/3');
  });
  it("limit_seq(binomial(2*n, n) / Sum(binomial(2*k, k), (k, 1, n)), n)", () => {
    const [k, n] = symbols('k n');
    expect(sympyStr(limitSeq(mul(pow(Sum(fn('binomial', [mul(Rational.of(2n, 1n, { gcd: 1n }), k), k]), [k, Rational.of(1n, 1n, { gcd: 1n }), n]), Rational.of(-1n, 1n, { gcd: 1n })), fn('binomial', [mul(Rational.of(2n, 1n, { gcd: 1n }), n), n])), n))).toBe('3/4');
  });
  it("limit_seq(Sum(k**2 * Sum(2**m/m, (m, 1, k)), (k, 1, n)) / (2**n*n), n)", () => {
    const [n, k, m] = symbols('n k m');
    expect(sympyStr(limitSeq(mul(pow(Rational.of(2n, 1n, { gcd: 1n }), mul(Rational.of(-1n, 1n, { gcd: 1n }), n)), pow(n, Rational.of(-1n, 1n, { gcd: 1n })), Sum(mul(pow(k, Rational.of(2n, 1n, { gcd: 1n })), Sum(mul(pow(Rational.of(2n, 1n, { gcd: 1n }), m), pow(m, Rational.of(-1n, 1n, { gcd: 1n }))), [m, Rational.of(1n, 1n, { gcd: 1n }), k])), [k, Rational.of(1n, 1n, { gcd: 1n }), n])), n))).toBe('4');
  });
  it("dominant(5*n**3 + 4*n**2 + n + 1, n)", () => {
    const n = new Sym('n');
    expect(sympyStr(dominant(add(Rational.of(1n, 1n, { gcd: 1n }), n, mul(Rational.of(4n, 1n, { gcd: 1n }), pow(n, Rational.of(2n, 1n, { gcd: 1n }))), mul(Rational.of(5n, 1n, { gcd: 1n }), pow(n, Rational.of(3n, 1n, { gcd: 1n })))), n))).toBe('5*n**3');
  });
  it("dominant(2**n + Sum(k, (k, 0, n)), n)", () => {
    const [n, k] = symbols('n k');
    expect(sympyStr(dominant(add(pow(Rational.of(2n, 1n, { gcd: 1n }), n), Sum(k, [k, Rational.of(0n, 1n, { gcd: 1n }), n])), n))).toBe('2**n');
  });
});

